import{_ as a,a0 as r,w as l,s as d,I as n,x as o,a1 as p,A as e,ao as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const c=JSON.parse('{"title":"在 Linux 上安装安卓 8.1 Oreo 来运行应用程序和游戏 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 上安装安卓 8.1 Oreo 来运行应用程序和游戏 | LCTT (201912) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 上安装安卓 8.1 Oreo 来运行应用程序和游戏 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 上安装安卓 8.1 Oreo 来运行应用程序和游戏 | LCTT (201912) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201912/20190217 Install Android 8.1 Oreo on Linux To Run Apps - Games","title":"在 Linux 上安装安卓 8.1 Oreo 来运行应用程序和游戏","tag":"201912","desc":""},"relativePath":"201912/20190217 Install Android 8.1 Oreo on Linux To Run Apps - Games.md","filePath":"[post].md"}'),u={name:"201912/20190217 Install Android 8.1 Oreo on Linux To Run Apps - Games.md"};function m(g,s,h,x,b,k){const i=r("Link");return l(),d("div",null,[s[25]||(s[25]=n("h1",{id:"在-linux-上安装安卓-8-1-oreo-来运行应用程序和游戏",tabindex:"-1"},[o("在 Linux 上安装安卓 8.1 Oreo 来运行应用程序和游戏 "),n("a",{class:"header-anchor",href:"#在-linux-上安装安卓-8-1-oreo-来运行应用程序和游戏","aria-label":"Permalink to “在 Linux 上安装安卓 8.1 Oreo 来运行应用程序和游戏”"},"​")],-1)),s[26]||(s[26]=n("p",null,[n("img",{src:"https://i2.wp.com/fosspost.org/wp-content/uploads/2019/02/android-8.1-oreo-x86-on-linux.png?resize=1237%2C527&ssl=1",alt:""})],-1)),n("p",null,[p(i,{href:"http://www.android-x86.org/"},{default:e(()=>[...s[0]||(s[0]=[o("android x86",-1)])]),_:1}),s[1]||(s[1]=o(" 是一个自由而开源的项目，将谷歌制作的安卓系统从 ARM 架构移植到了 x86 架构，可以让用户在他们的桌面电脑上运行安卓系统来享受所有的安卓功能和应用程序及游戏。",-1))]),s[27]||(s[27]=n("p",null,"在前一段时间，android x86 项目完成了安卓 8.1 Oreo 系统的 x86 架构移植。在这篇文章中，我们将解释如何在你的 Linux 系统上安装它，以便你能够随时使用你的安卓 用程序和游戏。",-1)),s[28]||(s[28]=n("h3",{id:"在-linux-上安装安卓-x86-8-1-oreo",tabindex:"-1"},[o("在 Linux 上安装安卓 x86 8.1 Oreo "),n("a",{class:"header-anchor",href:"#在-linux-上安装安卓-x86-8-1-oreo","aria-label":"Permalink to “在 Linux 上安装安卓 x86 8.1 Oreo”"},"​")],-1)),s[29]||(s[29]=n("h4",{id:"准备环境",tabindex:"-1"},[o("准备环境 "),n("a",{class:"header-anchor",href:"#准备环境","aria-label":"Permalink to “准备环境”"},"​")],-1)),n("p",null,[s[3]||(s[3]=o("首先，让我们下载 android x86 8.1 Oreo 系统镜像。你可以从",-1)),p(i,{href:"http://www.android-x86.org/download"},{default:e(()=>[...s[2]||(s[2]=[o("这个页面",-1)])]),_:1}),s[4]||(s[4]=o("下载它，只需单击 “android-x86_64-8.1-r1.iso” 文件下的 “View” 按钮。",-1))]),s[30]||(s[30]=t('<p>我们将在我们的 Linux 系统上使用 QEMU 来运行 android x86。QEMU 是一个非常好的模拟器软件，它也是自由而开源的，并且在所有主要的 Linux 发行版存储库中都是可用的。</p><p>在 Ubuntu/Linux Mint/Debian 上安装 QEMU：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get install qemu qemu-kvm libvirt-bin</span></span></code></pre></div><p>在 Fedora 上安装 QEMU：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf install qemu qemu-kvm</span></span></code></pre></div><p>对于其它发行版，只需要搜索 “qemu” 和 “qemu-kvm” 软件包，并安装它们。</p><p>在你安装 QEMU 后，我们将需要运行下面的命令来创建 <code>android.img</code> 文件，它就像某种分配给安卓系统的磁盘空间。所有安卓文件和系统都将位于该镜像文件中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>qemu-img create -f qcow2 android.img 15G</span></span></code></pre></div><p>我们在这里的意思是，我们想为该安卓系统分配一个最大 15GB 的磁盘空间，但是，你可以更改它到你想要的任意大小（确保它至少大于 5GB）。</p><p>现在，首次启动运行该安卓系统，运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo qemu-system-x86_64 -m 2048 -boot d -enable-kvm -smp 3 -net nic -net user -hda android.img -cdrom /home/mhsabbagh/android-x86_64-8.1-r1.iso</span></span></code></pre></div>',11)),n("p",null,[s[6]||(s[6]=o("将 ",-1)),s[7]||(s[7]=n("code",null,"/home/mhsabbagh/android-x86_64-8.1-r1.iso",-1)),s[8]||(s[8]=o(" 替换为你从 android x86 网站下载的文件的路径。关于我们在这里正在使用的其它选项的解释，你可以参考",-1)),p(i,{href:"https://fosspost.org/tutorials/use-qemu-test-operating-systems-distributions"},{default:e(()=>[...s[5]||(s[5]=[o("这篇文章",-1)])]),_:1}),s[9]||(s[9]=o("。",-1))]),s[31]||(s[31]=t(`<p>在你运行上面的命令后，该安卓系统将启动：</p><p><img src="https://i0.wp.com/fosspost.org/wp-content/uploads/2019/02/Android-8.1-Oreo-on-Linux-16.png?resize=694%2C548&amp;ssl=1" alt="" title="Install Android 8.1 Oreo on Linux To Run Apps &amp; Games 40 android 8.1 oreo on linux"></p><h4 id="安装系统" tabindex="-1">安装系统 <a class="header-anchor" href="#安装系统" aria-label="Permalink to “安装系统”">​</a></h4><p>从这个窗口中，选择 “Advanced options”, 它将引导到下面的菜单，你应如下在其中选择 “Auto_installation” ：</p><p><img src="https://i0.wp.com/fosspost.org/wp-content/uploads/2019/02/Android-8.1-Oreo-on-Linux-15.png?resize=673%2C537&amp;ssl=1" alt="" title="Install Android 8.1 Oreo on Linux To Run Apps &amp; Games 42 android 8.1 oreo on linux"></p><p>在这以后，安装器将告知你是否想要继续，选择 “Yes”：</p><p><img src="https://i1.wp.com/fosspost.org/wp-content/uploads/2019/02/Android-8.1-Oreo-on-Linux-14.png?resize=769%2C469&amp;ssl=1" alt="" title="Install Android 8.1 Oreo on Linux To Run Apps &amp; Games 44 android 8.1 oreo on linux"></p><p>接下来，安装器将无需你的指示而继续进行：</p><p><img src="https://i1.wp.com/fosspost.org/wp-content/uploads/2019/02/Android-8.1-Oreo-on-Linux-13.png?resize=767%2C466&amp;ssl=1" alt="" title="Install Android 8.1 Oreo on Linux To Run Apps &amp; Games 46 android 8.1 oreo on linux"></p><p>最后，你将收到这个信息，它表示你已经成功安装安卓 8.1 ：</p><p><img src="https://i0.wp.com/fosspost.org/wp-content/uploads/2019/02/Android-8.1-Oreo-on-Linux-12.png?resize=750%2C460&amp;ssl=1" alt="" title="Install Android 8.1 Oreo on Linux To Run Apps &amp; Games 48 android 8.1 oreo on linux"></p><p>现在，关闭 QEMU 窗口即可。</p><h4 id="启动和使用-安卓-8-1-oreo" tabindex="-1">启动和使用 安卓 8.1 Oreo <a class="header-anchor" href="#启动和使用-安卓-8-1-oreo" aria-label="Permalink to “启动和使用 安卓 8.1 Oreo”">​</a></h4><p>现在，安卓系统已经完全安装在你的 <code>android.img</code> 文件中，你应该使用下面的 QEMU 命令来启动它，而不是前面的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo qemu-system-x86_64 -m 2048 -boot d -enable-kvm -smp 3 -net nic -net user -hda android.img</span></span></code></pre></div><p>注意，我们所做的只是移除 <code>-cdrom</code> 选项及其参数。这是告诉 QEMU，我们不再想从我们下载的 ISO 文件启动，相反，从这个安装的安卓系统启动。</p><p>你现在能够看到安卓的启动菜单：</p><p><img src="https://i1.wp.com/fosspost.org/wp-content/uploads/2019/02/Android-8.1-Oreo-on-Linux-11.png?resize=754%2C456&amp;ssl=1" alt="" title="Install Android 8.1 Oreo on Linux To Run Apps &amp; Games 50 android 8.1 oreo on linux"></p><p>然后，你将进入第一个准备向导，选择你的语言并继续：</p><p><img src="https://i0.wp.com/fosspost.org/wp-content/uploads/2019/02/Android-8.1-Oreo-on-Linux-10.png?resize=850%2C559&amp;ssl=1" alt="" title="Install Android 8.1 Oreo on Linux To Run Apps &amp; Games 52 android 8.1 oreo on linux"></p><p>从这里，选择 “Set up as new” 选项：</p><p><img src="https://i0.wp.com/fosspost.org/wp-content/uploads/2019/02/Android-8.1-Oreo-on-Linux-09.png?resize=850%2C569&amp;ssl=1" alt="" title="Install Android 8.1 Oreo on Linux To Run Apps &amp; Games 54 android 8.1 oreo on linux"></p><p>然后，安卓将询问你是否想登录到你当前的谷歌账号。这步骤是可选的，但是这很重要，以便你随后可以使用谷歌 Play 商店：</p><p><img src="https://i1.wp.com/fosspost.org/wp-content/uploads/2019/02/Android-8.1-Oreo-on-Linux-08.png?resize=850%2C562&amp;ssl=1" alt="" title="Install Android 8.1 Oreo on Linux To Run Apps &amp; Games 56 android 8.1 oreo on linux"></p><p>然后，你将需要接受条款：</p><p><img src="https://i2.wp.com/fosspost.org/wp-content/uploads/2019/02/Android-8.1-Oreo-on-Linux-07-1.png?resize=850%2C561&amp;ssl=1" alt="" title="Install Android 8.1 Oreo on Linux To Run Apps &amp; Games 58 android 8.1 oreo on linux"></p><p>现在，你可以选择你当前的时区：</p><p><img src="https://i0.wp.com/fosspost.org/wp-content/uploads/2019/02/Android-8.1-Oreo-on-Linux-06.png?resize=850%2C569&amp;ssl=1" alt="" title="Install Android 8.1 Oreo on Linux To Run Apps &amp; Games 60 android 8.1 oreo on linux"></p><p>系统将询问你是否想启动一些数据收集功能。如果我是你的话，我将简单地全部关闭它们，像这样：</p><p><img src="https://i1.wp.com/fosspost.org/wp-content/uploads/2019/02/Android-8.1-Oreo-on-Linux-05.png?resize=850%2C559&amp;ssl=1" alt="" title="Install Android 8.1 Oreo on Linux To Run Apps &amp; Games 62 android 8.1 oreo on linux"></p><p>最后，你将有两种启动类型可供选择，我建议你选择 Launcher3 选项，并使其成为默认项：</p><p><img src="https://i1.wp.com/fosspost.org/wp-content/uploads/2019/02/Android-8.1-Oreo-on-Linux-04.png?resize=850%2C553&amp;ssl=1" alt="" title="Install Android 8.1 Oreo on Linux To Run Apps &amp; Games 64 android 8.1 oreo on linux"></p><p>然后，你将看到完整工作的安卓系统主屏幕：</p><p><img src="https://i0.wp.com/fosspost.org/wp-content/uploads/2019/02/Android-8.1-Oreo-on-Linux-03.png?resize=850%2C571&amp;ssl=1" alt="" title="Install Android 8.1 Oreo on Linux To Run Apps &amp; Games 66 android 8.1 oreo on linux"></p><p>从现在起，你可以做你想做的任何事情；你可以使用内置的安卓应用程序，或者你可以浏览你的系统设置来根据你的喜好进行调整。你可以更改你的系统的外观和体验，或者你可以像示例一样运行 Chrome ：</p><p><img src="https://i1.wp.com/fosspost.org/wp-content/uploads/2019/02/Android-8.1-Oreo-on-Linux-02.png?resize=850%2C555&amp;ssl=1" alt="" title="Install Android 8.1 Oreo on Linux To Run Apps &amp; Games 68 android 8.1 oreo on linux"></p><p>你可以开始从谷歌 Play 商店安装一些应用程序程序，像 WhatsApp 和其它的应用程序，以供你自己使用：</p><p><img src="https://i2.wp.com/fosspost.org/wp-content/uploads/2019/02/Android-8.1-Oreo-on-Linux-01.png?resize=850%2C557&amp;ssl=1" alt="" title="Install Android 8.1 Oreo on Linux To Run Apps &amp; Games 70 android 8.1 oreo on linux"></p><p>你现在可以用你的系统做任何你想做的事。恭喜！</p><h3 id="以后如何轻松地运行安卓-8-1-oreo" tabindex="-1">以后如何轻松地运行安卓 8.1 Oreo <a class="header-anchor" href="#以后如何轻松地运行安卓-8-1-oreo" aria-label="Permalink to “以后如何轻松地运行安卓 8.1 Oreo”">​</a></h3><p>我们不想总是不得不打开终端窗口，并写那些长长的 QEMU 命令来运行安卓系统，相反，我们想在我们需要时一次单击就运行它。</p><p>为此，我们将使用下面的命令在 <code>/usr/share/applications</code> 下创建一个名为 <code>android.desktop</code> 的新文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo nano /usr/share/applications/android.desktop</span></span></code></pre></div><p>并在其中粘贴下面的内容（右键单击然后粘贴）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[Desktop Entry]</span></span>
<span class="line"><span>Name=Android 8.1</span></span>
<span class="line"><span>Comment=Run Android 8.1 Oreo on Linux using QEMU</span></span>
<span class="line"><span>Icon=phone</span></span>
<span class="line"><span>Exec=bash -c &#39;pkexec env DISPLAY=$DISPLAY XAUTHORITY=$XAUTHORITY qemu-system-x86_64 -m 2048 -boot d -enable-kvm -smp 3 -net nic -net user -hda /home/mhsabbagh/android.img&#39;</span></span>
<span class="line"><span>Terminal=false</span></span>
<span class="line"><span>Type=Application</span></span>
<span class="line"><span>StartupNotify=true</span></span>
<span class="line"><span>Categories=GTK;</span></span></code></pre></div><p>再强调一次，你必需使用你系统上的本地镜像路径来替换 <code>/home/mhsabbagh/android.img</code> 。然后保存文件（<code>Ctrl+X</code>，然后按 <code>Y</code>，然后按回车）。</p><p>注意，我们需要使用 <code>pkexec</code> 来使用 root 权限运行 QEMU ，因为从较新的版本开始，普通用户不允许通过 libvirt 访问 KVM 技术；这就是为什么它将每次要求你输入 root 密码的原因。</p><p>现在，你将在应用程序菜单中看到安卓图标，你可以在你想使用安卓的任何时间来简单地单击该图标，QEMU 程序将启动：</p><p><img src="https://i0.wp.com/fosspost.org/wp-content/uploads/2019/02/Screenshot-at-2019-02-17-1539.png?resize=850%2C557&amp;ssl=1" alt="" title="Install Android 8.1 Oreo on Linux To Run Apps &amp; Games 72 android 8.1 oreo on linux"></p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>我们向你展示如何在你的 Linux 系统上安装和运行安卓 8.1 Oreo 。从现在起，在没有其它一些软件的（像 Blutsticks 和类似的方法）的情况下，你可以更容易地完成基于安卓的任务。在这里，你有一个完整工作和功能的安卓系统，你可以随心所欲地操作它，如果一些东西出错，你可以简单地干掉该镜像文件，然后随时再一次重新运行安装程序。</p><p>你之前尝试过 android x86 吗？你的体验如何？</p><hr>`,53)),n("p",null,[s[11]||(s[11]=o("via: ",-1)),p(i,{href:"https://fosspost.org/tutorials/install-android-8-1-oreo-on-linux"},{default:e(()=>[...s[10]||(s[10]=[o("https://fosspost.org/tutorials/install-android-8-1-oreo-on-linux",-1)])]),_:1})]),n("p",null,[s[16]||(s[16]=o("作者：",-1)),p(i,{href:"https://fosspost.org/author/mhsabbagh"},{default:e(()=>[...s[12]||(s[12]=[o("M.Hanny Sabbagh",-1)])]),_:1}),s[17]||(s[17]=o(" 选题：",-1)),p(i,{href:"https://github.com/lujun9972"},{default:e(()=>[...s[13]||(s[13]=[o("lujun9972",-1)])]),_:1}),s[18]||(s[18]=o(" 译者：",-1)),p(i,{href:"https://github.com/robsean"},{default:e(()=>[...s[14]||(s[14]=[o("robsean",-1)])]),_:1}),s[19]||(s[19]=o(" 校对：",-1)),p(i,{href:"https://github.com/wxy"},{default:e(()=>[...s[15]||(s[15]=[o("wxy",-1)])]),_:1})]),n("p",null,[s[22]||(s[22]=o("本文由 ",-1)),p(i,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[20]||(s[20]=[o("LCTT",-1)])]),_:1}),s[23]||(s[23]=o(" 原创编译，",-1)),p(i,{href:"https://linux.cn/"},{default:e(()=>[...s[21]||(s[21]=[o("Linux中国",-1)])]),_:1}),s[24]||(s[24]=o(" 荣誉推出",-1))])])}const L=a(u,[["render",m]]);export{c as __pageData,L as default};
